# English sentence has been owner-approved: ``ticket_duplicate_active``, ``ticket_idempotency_conflict``,
# ``ticket_recovery_unknown`` and ``ticket_recovered_created`` are PROPOSALS pending owner approval (they are spoken only
# while the fresh-ticket gate is ON; see docs/localization_review_hinglish_hindi.md).
REVIEW_STATUS = {"en": "approved", "hinglish": "draft: needs review by a fluent speaker",
                 "hi": "draft: needs review by a fluent speaker"}

